import Foundation

enum SoundPreparation {
    static func prepare(config: [String:Any], id: UUID) throws -> String {
        let names = ["piano","birds","ocean","ambient","voice"]
        let requested = config["sound"] as? String ?? "piano"
        let name = names.contains(requested) ? requested : "piano"
        guard let source = Bundle.main.url(forResource:name,withExtension:"wav",subdirectory:"Sounds") else { throw AlarmFailure.invalid }
        var data = try Data(contentsOf:source)
        // All bundled WAVs are generated by our script: 44-byte header, mono LE16 PCM.
        guard data.count > 44, String(data:data.prefix(4),encoding:.ascii) == "RIFF" else { throw AlarmFailure.invalid }
        let volume = min(1,max(0.1,(config["volume"] as? Double ?? 65)/100))
        let ramp = config["ramp"] as? Bool ?? true
        let seconds = min(180,max(10,config["rampSeconds"] as? Double ?? 45))
        for offset in stride(from:44,to:data.count-1,by:2) {
            let bits = UInt16(data[offset]) | (UInt16(data[offset+1]) << 8)
            let sample = Int16(bitPattern:bits)
            let time = Double((offset-44)/2)/22050
            let scale = volume*(ramp ? 0.08+0.92*min(1,time/seconds) : 1)
            let adjusted = UInt16(bitPattern:Int16(Double(sample)*scale))
            data[offset] = UInt8(adjusted & 255); data[offset+1] = UInt8(adjusted >> 8)
        }
        let folder = FileManager.default.urls(for:.libraryDirectory,in:.userDomainMask)[0].appendingPathComponent("Sounds")
        try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true)
        let file = "daybreak-\(id.uuidString).wav"
        try data.write(to:folder.appendingPathComponent(file),options:.atomic)
        return file
    }
}
